public class Main {
    public static void main(String[] args) {

        // Convert and display numbers in all 4 bases
        int[] values = {10, 42, 100, 255};

        System.out.printf("%-10s %-12s %-8s %-6s%n", "Decimal", "Binary", "Octal", "Hex");
        System.out.println("-".repeat(40));
        for (int v : values) {
            System.out.printf("%-10d %-12s %-8o %-6X%n",
                v,
                String.format("%8s", Integer.toBinaryString(v)).replace(" ", "0"),
                v, v);
        }

        // Bitwise operations on 42
        int n = 42;
        System.out.println("\n--- Bitwise on " + n + " ---");
        System.out.println("Binary  : " + Integer.toBinaryString(n));
        System.out.println("n & 15  : " + (n & 0x0F) + " (lower nibble)");
        System.out.println("n | 128 : " + (n | 0x80) + " (set bit 7)");
        System.out.println("n << 2  : " + (n << 2)   + " (×4)");
        System.out.println("n >> 1  : " + (n >> 1)   + " (÷2)");
        System.out.println("Even?   : " + ((n & 1) == 0));
    }
}
